from pathlib import Path
import base64
out=Path('.codex-run/mobile-compact-options')
u=['data:image/webp;base64,'+base64.b64encode(Path('public/assets/characters/portraits/'+n+'.webp').read_bytes()).decode() for n in ['aemeath','sigrika','denia']]
css='''*{box-sizing:border-box}body{margin:0;color:#443128;background:#eee7dd;font-family:"Microsoft YaHei",sans-serif}header{padding:18px 24px;background:#fffaf0;border-bottom:1px solid #c8b6a3}h1{font-size:19px;margin:0 0 8px}p{font-size:12px;line-height:1.7;color:#7c695a;margin:5px 0}nav{display:flex;gap:7px;margin-top:12px}button,select{font:inherit;font-size:12px;border:1px solid #b7a18a;border-radius:6px;background:#fffaf0;color:#443128;padding:7px 10px;cursor:pointer}button[aria-pressed=true]{background:#443128;color:#fffaf0}main{display:flex;gap:28px;padding:22px;align-items:flex-start}.phone{width:390px;flex:none;padding:10px;background:#fff8ef;background-image:linear-gradient(#c5dcd333 1px,transparent 1px),linear-gradient(90deg,#c5dcd333 1px,transparent 1px);background-size:18px 18px;border:1px solid #c3b09e;border-radius:16px}.room{display:flex;justify-content:space-between;align-items:center;height:27px;font-size:11px;padding:0 3px 7px}.room span:first-child{background:#e2eee2;border-radius:4px;padding:3px 5px}.card{display:grid;min-width:0;border:1px solid #806958;border-radius:10px;background:#fffbf3;padding:6px;gap:4px 8px;box-shadow:0 2px #d4c1ab}.card.active{border-color:#9b7331;background:#fff8e4}.portrait{grid-area:art;position:relative;height:100%;min-height:64px;overflow:hidden}.piece{position:absolute;inset:1px 0;overflow:hidden;--left:-18.333%;background:#fae9b9;clip-path:polygon(0 7%,40% 0,22% 94%,0 100%)}.piece:nth-child(2){--left:15%;background:#dcece4;clip-path:polygon(44% 3%,75% 0,55% 100%,25% 97%)}.piece:nth-child(3){--left:48.333%;background:#efdee4;clip-path:polygon(79% 5%,100% 0,100% 96%,59% 100%)}.piece img{width:70%;height:100%;position:absolute;left:var(--left);object-fit:cover}.identity{grid-area:id;display:flex;align-items:center;gap:5px;min-width:0;font-size:12px}.name{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.rank{font-size:10px;margin-left:auto;flex:none}.stone{width:10px;height:10px;background:radial-gradient(circle at 35% 25%,#777,#151515);border-radius:50%;flex:none}.white{background:radial-gradient(circle at 35% 25%,white,#bfc3c9);box-shadow:0 0 0 1px #afa99c}.clock{grid-area:clock;display:grid;grid-template-columns:auto 1fr;align-items:center;gap:2px 5px;min-width:0}.clock small{font-size:10px;color:#79624f}.digits{font:bold 26px Arial,sans-serif;justify-self:end;font-variant-numeric:tabular-nums;line-height:1}.digits em{font:normal 10px Arial,sans-serif;margin-left:4px;color:#9f682a}.track{height:4px;border-radius:3px;background:#dcd2c1;overflow:hidden;grid-column:1/-1}.track i{display:block;width:63%;height:100%;background:#649e8a}.active .track i{width:38%;background:#c47a3b}.active .digits{color:#bc472c}.stats{grid-area:stats;display:grid;grid-template-columns:repeat(3,1fr);gap:5px;font-size:11px;align-items:center;min-width:0}.stats span{display:flex;justify-content:space-between;gap:3px;white-space:nowrap}.stats b{font:700 16px Arial,sans-serif}.skill{grid-area:skill;border:0;border-top:1px solid #d8cbb7;border-radius:0;background:transparent;padding:3px 0 0;display:flex;justify-content:space-between;align-items:center;gap:5px;min-width:0;font-size:12px;text-align:left}.skill span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.skill b{font-size:11px;white-space:nowrap}.a .card{grid-template-columns:80px minmax(0,1fr);grid-template-rows:18px 30px 20px 22px;grid-template-areas:'art id' 'art clock' 'art stats' 'art skill'}.a .clock{grid-template-columns:auto 1fr}.a .stats span+span{border-left:1px solid #d8cbb7;padding-left:5px}.b .card{grid-template-columns:72px minmax(0,1fr) 94px;grid-template-rows:24px 28px 28px;grid-template-areas:'art id clock' 'art stats clock' 'art skill skill'}.b .clock{background:#eeeadd;border-radius:6px;padding:5px 6px;grid-template-columns:1fr;gap:3px}.b .active .clock{background:#ffe8a4}.b .digits{justify-self:center;font-size:25px}.b .clock small{text-align:center}.b .stats b{font-size:15px}.b .rank{margin-left:0}.b .stats span{flex-direction:column;align-items:center;gap:0;font-size:10px}.c .card{grid-template-columns:74px 89px minmax(0,1fr);grid-template-rows:20px 46px 26px;grid-template-areas:'id id id' 'art clock stats' 'art skill skill'}.c .identity{border-bottom:1px solid #ded0be;padding-bottom:4px}.c .clock{grid-template-columns:1fr;gap:3px;padding-right:7px;border-right:1px solid #ded0be}.c .clock small{font-size:9px}.c .digits{justify-self:start;font-size:27px}.c .stats{gap:5px}.c .stats span{flex-direction:column;align-items:center;font-size:10px;gap:4px}.c .stats b{font-size:22px}.c .skill{padding-top:3px}.board{aspect-ratio:1;width:100%;margin:10px 0;background:#e9c995;border:2px solid #735a42;border-radius:9px;padding:9px;box-shadow:0 2px #b59770}.board svg{display:block;width:100%;height:100%}.toolbar{display:flex;gap:6px;margin-top:10px}.toolbar button{flex:1;padding:8px 3px;font-size:11px;background:#fffaf0}.toolbar button:last-child{background:#e6ece3}.explain{max-width:260px}.explain h2{font-size:17px;margin:4px 0 10px}.explain p{font-size:13px}.controls{display:flex;flex-wrap:wrap;gap:7px;margin-top:18px}.single .piece{display:none}.single .piece:first-child{display:block;clip-path:none;background:transparent;inset:0}.single .piece:first-child img{left:0;width:100%;object-fit:contain}dialog{border:1px solid #735a42;background:#fffaf0;color:#443128;border-radius:10px;padding:20px;max-width:290px}dialog::backdrop{background:#44312855}@media(max-width:650px){main{display:block;padding:12px 6px}.phone{max-width:100%}.explain{margin:20px auto;max-width:390px}header{padding:14px}nav{flex-wrap:wrap}}'''
def card(active):
 art='<div class="portrait">'+''.join('<div class="piece"><img alt="角色头像" src="'+x+'"></div>' for x in u)+'</div>'
 return '<article class="card '+('active' if active else '')+'">'+art+'<div class="identity"><i class="stone '+('' if active else 'white')+'"></i><span class="name">'+('moming' if active else '春日棋友')+'</span><span class="rank">7段</span></div><div class="clock"><small>'+('读秒' if active else '主时间')+'</small><div class="digits">'+('30<em>×1</em>' if active else '04:32')+'</div><div class="track"><i></i></div></div><div class="stats"><span>提子<b>9</b></span><span>除子<b>4</b></span><span>超频<b>7</b></span></div><button class="skill"><span>✧ 课定启动</span><b>剩余 1 次 ›</b></button></article>'
lines=''.join(f'<path d="M {10+i*10} 10 V 190 M 10 {10+i*10} H 190"/>' for i in range(19))
stones=''.join(f'<circle cx="{x}" cy="{y}" r="4.5" fill="{c}" stroke="#584c3c" stroke-width=".3"/>' for x,y,c in [(40,40,'#292828'),(160,160,'#faf8ee'),(160,40,'#292828'),(40,160,'#faf8ee'),(100,100,'#292828'),(100,110,'#faf8ee'),(110,100,'#292828'),(90,100,'#faf8ee'),(110,110,'#292828')])
board='<div class="board"><svg viewBox="0 0 200 200"><g stroke="#735a42" stroke-width=".4">'+lines+'</g>'+stones+'</svg></div>'
html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>移动对弈 · 紧凑三版</title><style>'+css+'</style><header><h1>移动对弈 · 紧凑三版</h1><p>完整手机比例：双方信息区＋接近满宽的正方形棋盘 · 无错落、无长空条</p><nav><button data-v="a">A · 头像侧栏</button><button data-v="b">B · 右置棋钟</button><button data-v="c">C · 横向仪表</button></nav></header><main><section class="phone a"><div class="room"><span>队际赛 # A7K2</span><span>第 24 手　···</span></div>'+card(False)+board+card(True)+'<div class="toolbar"><button>成员</button><button>记录</button><button>认输</button><button>停一手</button></div></section><aside class="explain"><h2></h2><p class="desc"></p><p class="measure"></p><div class="controls"><select aria-label="手机宽度"><option>390</option><option>320</option><option>430</option></select><button id="single">单人 / 队际头像</button><button id="long">长用户名</button></div><p>此页为布局样板，棋盘与操作栏仅展示比例，未连接真实对局。</p></aside></main><dialog><strong>样板交互</strong><p>正式接入时保留对应功能及确认流程。</p><button id="close">关闭</button></dialog>'+r'''<script>const data={a:['A · 头像侧栏','头像占独立窄列，姓名、时间、统计、技能纵向紧排。信息完整，头像相对清楚。'],b:['B · 右置棋钟','棋钟固定在右上角，技能利用底部横向空间。三版中高度最小，为棋盘留白最多。'],c:['C · 横向仪表','顶部身份行，中间头像、时间、统计三组并列，技能贴在下方。数字最突出。']};function measure(){requestAnimationFrame(()=>{const c=document.querySelector('.card').getBoundingClientRect(),b=document.querySelector('.board').getBoundingClientRect();document.querySelector('.measure').textContent=`单侧信息区 ${Math.round(c.height)}px · 棋盘 ${Math.round(b.width)} × ${Math.round(b.height)}px`})}function show(v){document.querySelector('.phone').className='phone '+v;document.querySelector('h2').textContent=data[v][0];document.querySelector('.desc').textContent=data[v][1];document.querySelectorAll('[data-v]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.v===v));measure()}document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>show(b.dataset.v));document.querySelector('select').onchange=e=>{document.querySelector('.phone').style.width=e.target.value+'px';measure()};document.querySelector('#single').onclick=()=>document.querySelectorAll('.portrait').forEach(p=>p.classList.toggle('single'));document.querySelector('#long').onclick=()=>document.querySelectorAll('.name').forEach(n=>n.textContent=n.textContent.length>8?'moming':'用于检查排版的很长的用户名');document.querySelectorAll('.skill,.toolbar button').forEach(b=>b.onclick=()=>document.querySelector('dialog').showModal());document.querySelector('#close').onclick=()=>document.querySelector('dialog').close();show('a');</script></html>'''
(out/'index.html').write_text(html,encoding='utf-8')
